    song_number: 287,
    Song_number_by_Nambikaiyen_Geethagal: 190,
    title_tamil: `கிருபை! எம்மை சூழ்ந்து`,
    title_english: `Kirubai emmai soozhnthu`,
    lyrics: `கிருபை! எம்மை சூழ்ந்து கொள்ளும் 
தம் கிருபை
கர்த்தரில் மகிழ்வோம்
களி கூர்ந்திடுவோம்
கண்டடைந்தோம் கிருபை.

1. யோர்தானைக் கடந்து வந்தோம் ~ எங்கள்
இயேசுவின் பெலம் அடைந்தோம்
சேனையின் கர்த்தர் முன்னே நடந்தார்
சோர்வின்றிக் காத்துக் கொண்டார்
 ~ கிருபை! எம்மை

2. தேசமே பயப்படாதே எங்கள்
தேவன் கிரியை செய்கிறார்
தேசத்தின் நன்மை ஷேமம் அருள்வார்
தாசகர்கள் வேண்டிடுவோம்
 ~ கிருபை! எம்மை

3. கர்த்தர் இவ்வாண்டினிலே பெருங்
காரியம் செய்திடுவார்
கால் வைக்கும் தேசம் இயேசு தருவார்
காத்திருந்தே அடைவோம்
 ~ கிருபை! எம்மை

4. ஆண்டுகள் நன்மையினால் ~ முடி
சூண்டு வளம் பெருக
தேசத்தின் மீதே கண்களை வைத்தே
பாசமாய் நோக்கிடுவார்
 ~ கிருபை! எம்மை

5. ஜாதி ஜனங்களையும் ~ வந்து
மோதி அசைந்திடுவார்
காத்து தவிக்கும் உள்ளம் மகிழும்
கர்த்தரே வந்திடுவார்
 ~ கிருபை! எம்மை`
